const raw = $input.first().json.content?.find(b=>b.type==='text')?.text || '';
const clean = raw.replace(/```json|```/g,'').trim();
let parsed;
try { parsed = JSON.parse(clean); }
catch(e) {
  const match = clean.match(/\{[\s\S]*\}/);
  if (match) { try { parsed = JSON.parse(match[0]); } catch(e2) { throw new Error('Cannot parse: ' + clean.slice(0,200)); } }
  else throw new Error('No JSON found: ' + clean.slice(0,200));
}
const si = $('Sanitize Inputs').first().json;
return [{json: {
  hook:           parsed.hook || '',
  body:           parsed.body || '',
  hashtags:       parsed.hashtags || '#ArakLighting #ArchitecturalLighting',
  image_prompt:   parsed.image_prompt || '',
  trending_angle: parsed.trending_angle || '',
  post_strategy:  parsed.post_strategy || '',
  topic:          si.safe_topic,
  tone:           si.tone,
  post_type:      si.post_type,
  style:          si.style,
  content_route:  si.content_route,
  include_image:  si.include_image,
  aspect_ratio:   si.aspect_ratio,
}}];

const styleMap = {
  "photorealistic":   "architectural photography, Canon EOS R5, professional lighting, hyper-detailed, 4K, wide format",
  "dramatic":         "cinematic lighting, deep shadows, high contrast, noir atmosphere, professional corporate",
  "minimalist":       "clean lines, soft diffused light, Scandinavian aesthetic, white space, elegant",
  "warm_interior":    "warm amber tones, luxury interior, golden hour, premium hospitality space",
  "cool_commercial":  "cool white 5000K, modern commercial architecture, crisp, glass and steel, corporate luxury",
  "facade_exterior":  "architectural exterior night photography, facade illumination, dramatic night sky"
};
const si = $('Sanitize Inputs').first().json;
const base = $('Parse Post').first().json.image_prompt || si.safe_topic || 'architectural lighting';
const styleStr = styleMap[si.style] || styleMap['photorealistic'];
const finalPrompt = base + ', ' + styleStr + ', Arak Lighting Saudi Arabia, ultra high detail, professional LinkedIn visual, wide 16:9 composition';
return [{json: { final_prompt: finalPrompt, style: si.style }}];

