const raw = $input.first().json.content?.find(b=>b.type==='text')?.text || '';
const clean = raw.replace(/```json|```/g,'').trim();
let parsed;
try { parsed = JSON.parse(clean); }
catch(e) {
  const match = clean.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : {hook: '', body: clean, hashtags: '#ArakLighting'};
}
return [{json: { hook: parsed.hook || '', body: parsed.body || '', hashtags: parsed.hashtags || '#ArakLighting' }}];

